import{_ as n,l as r,o as e,c as s,v as o,p as l,x as t,d,i as c,S as m}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"不确定性冲击","description":"","frontmatter":{"title":"不确定性冲击","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/uncertainty-shocks.md","filePath":"econ/uncertainty-shocks.md","lastUpdated":1789023840000}'),p={name:"econ/uncertainty-shocks.md"};function h(E,a,A,_,u,B){const i=r("Mermaid");return e(),s("div",null,[a[1]||(a[1]=o('<h1 id="不确定性冲击" tabindex="-1">不确定性冲击 <a class="header-anchor" href="#不确定性冲击" aria-label="Permalink to &quot;不确定性冲击&quot;">​</a></h1><div class="epigraph"><p>方差上升本身会推迟不可逆投资、提高预防性储蓄、在金融摩擦下抬升利差——不必先有均值变坏。</p><footer>—— Bloom, The Impact of Uncertainty Shocks, Econometrica 2009；Fernández-Villaverde, Guerrón-Quintana, Rubio-Ramírez and Uribe；Arellano, Bai and Kehoe</footer></div><p><a href="/econ/news-shocks">上一课</a>动的是条件均值。本课缺口是<strong>二阶矩冲击</strong>。扰动法已说过一阶确定性等价看不见它；现在经济上要用到。不重写新闻的 SVAR 限制。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Bloom：不确定性跳升（股市隐含波动、政策不确定性指数）之后，投资与雇佣出现短暂急停，因为不可逆与 \\((S,s)\\) 的等待价值。开放与 NK：不确定性经风险溢价与需求下降制造衰退。Fernández-Villaverde 等把时变波动写进小型开放或财政规则。缺口是给「信心」一条可与新闻正交的方差通道，而不是把 VIX 当均值新闻的代理而不声明。</p><p><span class="marginnote">Bloom, <em>Econometrica</em> 77(3), 2009。Baker, Bloom and Davis 的 EPU。Jurado, Ludvigson and Ng 的宏观不确定性。Basu and Bundick 的 NK 不确定性。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>冲击：\\(\\sigma_t\\) 的 AR。机制菜单：（i）实物期权 / 不可逆（企业异质课的 \\((S,s)\\)），（ii）预防性（缓冲存量），（iii）金融加速器（净值的期权价值、违约界），（iv）名义刚性下的需求下降（谨慎消费 + 粘性价格）。一阶线性 DSGE 必须升到至少三阶或用带 \\(\\sigma_t\\) 的非线性，否则通道关掉。识别：符号限制或外部工具，VIX 既含不确定也含风险溢价与杠杆，标签要小心。</p>',8)),(e(),l(m,null,{default:t(()=>[c(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SIG%5B%22%CF%83%20%E4%B8%8A%E5%8D%87%22%5D%20--%3E%20WAIT%5B%22%E7%AD%89%E5%BE%85%3A%20%E6%8A%95%E8%B5%84%E9%9B%87%E4%BD%A3%22%5D%0A%20%20SIG%20--%3E%20PREC%5B%22%E9%A2%84%E9%98%B2%E6%80%A7%E5%82%A8%E8%93%84%22%5D%0A%20%20SIG%20--%3E%20SPR%5B%22%E5%88%A9%E5%B7%AE%20%2F%20%E8%BF%9D%E7%BA%A6%E7%95%8C%22%5D%0A%20%20WAIT%20--%3E%20Y%5B%22%E4%BA%A7%E5%87%BA%E4%B8%8B%E9%99%8D%22%5D%0A%20%20PREC%20--%3E%20Y%0A%20%20SPR%20--%3E%20Y%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>与诊断性：主观方差也可以因代表性而误读；本课先取客观 \\(\\sigma\\)。与疏忽：容量在更嘈杂的世界更不够，惯性上升。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是凸性与期权。坏状态更坏的可能性提高等待价值（若不可逆），也提高 \\(u&#39;\\) 的期望（若谨慎）。金融：不确定性使外部股权更贵或抵押更紧。HANK：高 MPC 家庭的收入风险升，加总 MPC 升，需求更脆。代表 RANK 的不确定性效应往往偏小，除非把需求与金融摩擦开够。</p><p>测量：隐含波动是价格，含风险价格；截面离散是结果也可能是测量。模型应声明用哪一个当 \\(\\sigma_t\\) 的观测。</p><p><span class="marginnote">Arellano, Bai and Kehoe 对企业不确定性与金融摩擦。本课不把期权定价公式重推。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不交易 VIX。不把所有衰退归因于 \\(\\sigma\\)。灾害风险（Barro、Rietz）是均值的左尾厚度，与时变 \\(\\sigma\\) 相关但不是同一冲击。主权利差的不确定性后课违约。</p><p>后课默认：方差冲击有实物期权、预防性、金融三条主通道；一阶 SW 默认看不见。下一课：用调查把预期的均值与分歧测出来。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>不确定性冲击动二阶矩，经等待、预防性与利差压活动。</li><li>需要非线性或显式 \\(\\sigma_t\\)，一阶确定性等价不够。</li><li>VIX 等观测混有风险价格，识别要声明。</li><li>出处：Bloom, <em>Econometrica</em> 2009。</li></ul>',10))])}const P=n(p,[["render",h]]);export{f as __pageData,P as default};
